function fetchPrice(prices, id) {
  // имитация запроса к API
  return Promise.resolve(prices[id]);
}

async function cartTotal(ids, prices) {
  const list = await Promise.all(ids.map((id) => fetchPrice(prices, id)));
  return list.reduce((sum, p) => sum + p, 0);
}

